function result=runV4TrackAFormalR8()
root=v4SetupPaths();c=sf12NoLdroSf11FlowConfig();m=jsondecode(fileread(fullfile(root,'config','paperReceiverParameterManifest_stage3s_v01.json')));p=m.parameters;p.bootstrapStepBins=0.05;p.highShiftThresholdBins=100;planHash=v4Sha256(fullfile(root,'R8_STAGE55_PREAMBLE_ADAPTIVE.md'));algorithmSignature=v4Sha256([planHash v4Sha256(fullfile(root,'src','paper_anchor','v4TrackAStage55PreambleAdaptiveDecode.m')) v4Sha256(v4CanonicalJson(p))]);pool=gcp('nocreate');if isempty(pool)||pool.NumWorkers~=2,if ~isempty(pool),delete(pool);end;parpool('local',2);end;cells=cell(20,1);parfor index=1:20,ci=ceil(index/10);si=mod(index-1,10)+1;cells{index}=v4RunTrackAFormalCellR8(root,c,p,algorithmSignature,ci,si);end;result=struct('status','PASS','algorithmVersion','Stage55-A-preamble-adaptive-v5','algorithmSignature',algorithmSignature,'totalPairedPackets',400000,'cells',{cells});folder=fullfile(root,'results','formal','track_a','R8-preamble-adaptive');save(fullfile(folder,'formal_index.mat'),'result','-v7.3');
end
